<script setup>
import {ref,computed,onMounted} from 'vue'
import PortPicker from './PortPicker.vue'
import {api,post,references,portLabel,boxes} from './quotationApi'
defineProps({user:Object})
const emit=defineEmits(['preview','catalog','excel','review','uploads'])
const refs=ref({ports:[],routes:[],carriers:[],suppliers:[],source_series:[]})
const defaults=ref(null),currencies=ref([]),rows=ref([]),form=ref(null),current=ref(null),issues=ref([]),busy=ref(false),loading=ref(true),error=ref(''),message=ref('')
const routeOptions=computed(()=>{const port=refs.value.ports.find(p=>p.id===form.value?.destination_port_id);return refs.value.routes.filter(r=>r.active&&port?.route_ids.includes(r.id))})
const seriesLabel=row=>`${refs.value.suppliers.find(s=>s.id===row.supplier_id)?.name||'—'} · ${row.name}`
const portName=id=>portLabel(refs.value.ports.find(p=>p.id===id))
async function load(){loading.value=true;error.value='';try{const [r,d,s]=await Promise.all([references(),api('/api/manual-drafts/defaults'),api('/api/manual-drafts')]);refs.value=r;defaults.value=d.data;currencies.value=d.currencies;rows.value=s.items}catch(e){error.value=e.message}finally{loading.value=false}}
function edit(row=null){current.value=row;form.value=JSON.parse(JSON.stringify(row?.data||defaults.value));issues.value=row?.issues||[];message.value='';error.value=''}
async function save(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{const suffix=current.value?`/${current.value.id}?expected_revision=${current.value.revision}`:'';const saved=await post('/api/manual-drafts'+suffix,form.value,current.value?'PUT':'POST');current.value=saved;form.value=structuredClone(saved.data);issues.value=saved.issues;rows.value=(await api('/api/manual-drafts')).items;message.value=saved.ready_for_review?'草稿已保存，字段检查通过。尚未审批，仅可在草稿试查中查看。':`草稿已保存，还有${saved.issues.length}项需要补齐或修正。`}catch(e){error.value=e.message}finally{busy.value=false}}
function destinationChanged(id){form.value.destination_port_id=id;form.value.route_id=''}
function originChanged(id){form.value.origin_port_id=id;form.value.origin_confirmed=false}
onMounted(load)
</script>
<template><section class="quotes-panel">
  <div class="catalog-heading"><div><button @click="$emit('review')">差异对比与审批 →</button><h2>报价草稿</h2><p>人工录入或Excel导入后校对。核对草稿后，进入差异对比与审批。</p></div><div class="form-actions"><button class="small-button primary" :disabled="busy" @click="emit('uploads')">上传原件与提取报价</button><button class="small-button" :disabled="busy" @click="emit('excel')">Excel导入</button><button class="small-button primary" :disabled="loading||busy" @click="edit()">新增人工报价</button></div></div>
  <div class="quote-banner">未审批草稿不进入正式报价查询；已入库记录保留供追溯。<button class="table-button" @click="emit('preview')">进入草稿试查 →</button><button v-if="user?.role==='admin'" class="table-button" @click="emit('catalog')">维护船公司／来源 →</button></div>
  <p v-if="error" role="alert" class="feedback error">{{error}}</p><p v-if="message" role="status" class="feedback success">{{message}}</p><p v-if="loading" role="status">正在加载草稿…</p>
  <form v-if="form" class="catalog-form quote-form" @submit.prevent="save"><h3>{{current?'编辑报价草稿':'新增人工报价'}}</h3><div v-if="['excel','ai'].includes(current?.origin_kind)" class="quote-banner"><b>{{current?.origin_kind==='ai'?'AI提取草稿，须人工校对':'Excel导入草稿，未审批'}}</b><p v-for="(e,i) in current.evidence.filter(e=>e.original_name)" :key="i">{{e.original_name}} · {{e.worksheet}} · {{e.cell_range}} {{e.page_number?`第${e.page_number}页／张`:''}} <a v-if="e.file_id" :href="`/api/uploads/files/${e.file_id}/original`" download>下载原件核对</a></p><details><summary>查看原始导入字段</summary><dl><template v-for="(value,label) in current.original_import" :key="label"><dt>{{label}}</dt><dd>{{value||'（空）'}}</dd></template></dl></details></div><fieldset :disabled="busy"><div class="form-fields">
    <PortPicker label="起运港" :model-value="form.origin_port_id" @update:model-value="originChanged" :ports="refs.ports"/><PortPicker label="目的港" :model-value="form.destination_port_id" @update:model-value="destinationChanged" :ports="refs.ports"/>
    <label class="check-label"><input type="checkbox" v-model="form.origin_confirmed">已核对起运港</label><label>航线<select v-model="form.route_id"><option value="">请选择目的港所属航线</option><option v-for="r in routeOptions" :key="r.id" :value="r.id">{{r.name}}</option></select></label>
    <label>船公司<select v-model="form.carrier_id"><option value="">请选择</option><option v-for="c in refs.carriers.filter(c=>c.active)" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>协议／报价系列<select v-model="form.source_series_id"><option value="">请选择供应商及报价系列</option><option v-for="s in refs.source_series.filter(s=>s.active&&refs.suppliers.some(p=>p.id===s.supplier_id&&p.active))" :key="s.id" :value="s.id">{{seriesLabel(s)}}</option></select></label>
    <label>币种<select v-model="form.currency"><option value="">请选择</option><option v-for="c in currencies" :key="c">{{c}}</option></select></label><label>费用口径<input v-model="form.fee_basis" maxlength="160" placeholder="例如 CY-CY；不代表全包"></label>
  </div><h4>每箱成本价</h4><div class="box-prices"><div v-for="box in boxes" :key="box"><label>{{box}}价格<input v-model="form.prices[box]" inputmode="decimal" maxlength="32" placeholder="留空表示缺价"></label><label class="check-label"><input type="checkbox" v-model="form.zero_confirmed" :value="box">确认{{box}}零运费</label></div></div>
  <div class="form-fields"><label>有效期起<input type="date" v-model="form.valid_from"></label><label>有效期止<input type="date" v-model="form.valid_to"></label><label>有效期依据<select v-model="form.validity_basis"><option value="">请选择</option><option value="ETD">ETD开船日</option><option value="other">其他依据（保留草稿）</option><option value="unknown">不明（保留草稿）</option></select></label><label>有效期原文<input v-model="form.validity_original" maxlength="1000"></label>
    <label>服务类型<select v-model="form.service_kind"><option value="">请选择</option><option value="direct">直达</option><option value="transshipment">中转</option><option value="unknown">待确认</option></select></label><label>服务标识<input v-model="form.service_key" maxlength="160" placeholder="例如供应商给出的服务／航线名称"></label><label>途径路径<input v-model="form.path_text" maxlength="2000"></label><label>船期<input v-model="form.sailing" maxlength="300" placeholder="例如周三／周班"></label><label>航程天数<input v-model="form.transit_days" inputmode="numeric" maxlength="20" placeholder="正整数；区间请放入备注"></label>
    <label>已含费用<input v-model="form.included_fees" maxlength="2000"></label><label>另计费用<input v-model="form.extra_fees" maxlength="2000"></label><label>待确认费用<input v-model="form.unknown_fees" maxlength="2000"></label><label>适用条件<textarea v-model="form.conditions" maxlength="2000" placeholder="限重、货类、最低箱量等"></textarea></label><label>备注<textarea v-model="form.remark" maxlength="4000"></textarea></label><label class="check-label"><input type="checkbox" v-model="form.conditions_confirmed">已人工核对适用条件</label><label>手工报价依据<textarea v-model="form.manual_note" maxlength="2000" placeholder="记录供应商报价时间、协议编号或其他可追溯依据"></textarea></label>
  </div><div v-if="issues.length" class="validation-list" role="status"><b>待补齐／修正 {{issues.length}} 项</b><ul><li v-for="issue in issues" :key="issue.field">{{issue.message}}</li></ul></div><div class="form-actions"><button class="small-button primary" type="submit">{{busy?'保存中…':'保存草稿并校验'}}</button><button type="button" class="small-button" @click="form=null">关闭编辑</button></div></fieldset></form>
  <div class="draft-list"><p>已保存 {{rows.length}} 条报价草稿</p><article v-for="row in rows" :key="row.id"><div><b>{{portName(row.data.destination_port_id)}}</b><p>{{row.data.service_key||'服务待补齐'}} · {{row.data.currency||'币种待补齐'}} · {{row.ready_for_review?'字段检查通过':`待修正${row.issues.length}项`}}</p><small>草稿 {{row.id.slice(0,8)}} · 修订{{row.revision}} · {{({pending:'审批中',approved:'已入库',rejected:'已驳回',withdrawn:'已撤回',draft:'未发布'})[row.batch_status]}}</small></div><button class="small-button" :disabled="!['draft','rejected','withdrawn'].includes(row.batch_status)" @click="edit(row)">编辑草稿</button></article><p v-if="!loading&&!rows.length">暂无草稿，可新增人工报价或使用Excel导入。</p></div>
</section></template>
